import { usePnlProfitText } from '@/hook/common/usePnlProfitText'
import { usePumpTokenHelper } from '@/hook/pump/usePumpTokenHelper'
import { useVirtualLiquidity } from '@/hook/pump/useVirtualLiquidity'
import { PumpToken } from '@/type/pump'
import useGlobalToast from '@cetus/hooks/src/useGlobalToast'
import useTokenPrice from '@cetus/hooks/src/useTokenPrice'
import useWindowWidth from '@cetus/hooks/src/useWindowWidth'
import { HTextLabelBox, Icon } from '@cetus/ui-kit'
import {
  Decimal,
  downloadImage,
  fallbackDownload,
  formatCreatedTime,
  formatCurrency,
  formatNumber,
  formatPercentage,
  fromDecimalsAmountFix
} from '@cetus/utils'
import { BondingCurveStatus } from '@cetusprotocol/cetus-sui-pump-sdk'
import {
  Box,
  Button,
  HStack,
  Heading,
  Modal,
  ModalBody,
  ModalCloseButton,
  ModalContent,
  ModalHeader,
  ModalOverlay,
  Stack,
  Text,
  VStack
} from '@chakra-ui/react'
import html2canvas from 'html2canvas'
import VTextLabelBox from '../../../../ui-kit/src/components/VTextLabelBox'
import TokenImg from '../common/TokenImg'

type TokenShareModelProps = {
  token: PumpToken
  isOpen: boolean
  onClose: () => void
}

export default function TokenShareModel(props: TokenShareModelProps) {
  const { isOpen, onClose, token } = props

  const { isApp } = useWindowWidth()

  const { color, percentText } = usePnlProfitText({ initNum: token?.price_change_24h || '0' })
  const { getTokenAmountValue } = useTokenPrice()
  const { market_cap, raising_progress } = usePumpTokenHelper(token)
  const { showCommonToast } = useGlobalToast()
  const { virtualLiquidityValue } = useVirtualLiquidity(token)

  const captureCard = async (action: number) => {
    const node: any = document.getElementById('token_card')
    const options: any = { scale: 1, useCORS: true, allowTaint: true, backgroundColor: null, scrollY: 0, scrollX: 0 }

    html2canvas(node, options)
      .then(canvas => {
        if (action == 0) {
          const imgDt = canvas.toDataURL('png')
          downloadImage(imgDt, token?.TokenDetail.symbol + '.png')
          showCommonToast('Image downloaded')
          return
        }
        if (action == 1) {
          canvas.toBlob(async blob => {
            if (blob) {
              try {
                await navigator.clipboard.write([
                  new ClipboardItem({
                    'image/png': blob
                  })
                ])
              } catch (error) {
                fallbackDownload(blob, token?.TokenDetail.symbol + '.png')
              }
            }
          }, 'image/png')
          showCommonToast('Image copied')
          return
        }
      })
      .catch(error => {
        console.error('图片生成失败:', error)
      })

    if (action === 2) {
      const twitterUrl = `https://twitter.com/intent/tweet?url=${encodeURIComponent(window.location.href)}`
      window.open(twitterUrl, '_blank')
      return
    }
  }

  return (
    <Modal isOpen={isOpen} onClose={onClose}>
      <ModalOverlay />
      <ModalContent bg="transparent" borderColor="transparent" minW={{ base: '', lg: '620px' }}>
        <ModalHeader>
          <Heading fontWeight="500" fontSize="16px">
            Share Coin Stats
          </Heading>
        </ModalHeader>
        <ModalCloseButton />
        <ModalBody pb="30px" textAlign="center" id="token_card">
          <VStack w="100%" bg="background" border="1px solid" borderColor="border" borderRadius="20px">
            <Stack
              gap={{ base: '12px', lg: '40px' }}
              p="20px"
              w="100%"
              bg="menu_item_bg"
              border="1px solid"
              borderColor="border"
              borderRadius="20px"
              justifyContent="start"
              flexDirection={{ base: 'column', lg: 'row' }}
            >
              <Box>
                <TokenImg
                  src={token?.TokenDetail?.image || ''}
                  wrapStyle={isApp ? { w: '100%', h: '100%', p: '12px' } : { w: '160px', h: '160px', minW: '160px', minH: '160px', p: '12px' }}
                  imageStyle={{ objectFit: 'cover' }}
                />
              </Box>

              <VStack gap="8px" alignItems="start" mt="4px">
                <Heading fontSize="20px" color="text_caption" h="20px" lineHeight="20px">
                  {`${token?.TokenDetail.name || '--'} (${token?.TokenDetail.symbol || '--'})`}
                </Heading>

                <Text mt={{ base: '4px', lg: '20px' }}>Contract:</Text>
                <Text color="text_caption" maxW={{ base: '100%', lg: '342px' }} textAlign="start">
                  {token?.TokenDetail.coin_type}
                </Text>
              </VStack>
            </Stack>
            {/* 内容区域 */}
            {isApp ? (
              <VStack w="100%" p="20px" alignItems="start" gap="20px">
                <HStack w="100%" justifyContent="space-between" h="14px" lineHeight="1">
                  <Text>Price</Text>
                  <Text color="text_caption">{formatNumber(token?.current_ui_price, 9, undefined, Decimal.ROUND_DOWN)} SUI</Text>
                </HStack>

                <HTextLabelBox
                  leftLabel="Market Cap"
                  leftLabelFontSize="14px"
                  rightValueFontSize="14px"
                  rightValue={`$${formatNumber(market_cap, 2)} (${formatPercentage(raising_progress || '0')})`}
                  wrapStyle={{
                    h: '14px',
                    lineHeight: '1'
                  }}
                />

                <HTextLabelBox
                  leftLabel={token.status >= BondingCurveStatus.MIGRATED ? 'Liquidity' : 'Virtual Liquidity'}
                  leftLabelFontSize="14px"
                  rightValueFontSize="14px"
                  rightValue={virtualLiquidityValue ? formatCurrency(virtualLiquidityValue, 2) : '-'}
                  wrapStyle={{
                    h: '14px',
                    lineHeight: '1'
                  }}
                />

                <HTextLabelBox
                  leftLabel="24H Volume"
                  leftLabelFontSize="14px"
                  rightValueFontSize="14px"
                  rightValue={fromDecimalsAmountFix(token?.volume_24h || '0', 9) + ' SUI'}
                  wrapStyle={{
                    h: '14px',
                    lineHeight: '1'
                  }}
                />

                <HTextLabelBox
                  leftLabel="Token Created"
                  leftLabelFontSize="14px"
                  rightValueFontSize="14px"
                  rightValue={formatCreatedTime(token?.TokenDetail.create_timestamp, false) || '-'}
                  wrapStyle={{
                    h: '14px',
                    lineHeight: '1'
                  }}
                />
              </VStack>
            ) : (
              <HStack w="100%" justifyContent="space-between" p="20px" alignItems="start">
                {/* 左边 */}
                <VStack gap="26px" alignItems="start">
                  <VTextLabelBox
                    title={'Price'}
                    value={
                      <HStack>
                        <Text color="text_caption">{formatNumber(token?.current_ui_price, 9, undefined, Decimal.ROUND_DOWN)} SUI</Text>
                      </HStack>
                    }
                  />

                  <VTextLabelBox title="24H Volume" value={fromDecimalsAmountFix(token?.volume_24h || '0', 9) + ' SUI'} />
                </VStack>
                {/* 中间 */}
                <VStack gap="26px" alignItems="start">
                  <VTextLabelBox title="Market Cap" value={`$${formatNumber(market_cap, 2)} (${formatPercentage(raising_progress || '0')})`} />

                  <VTextLabelBox title="Token Created" value={formatCreatedTime(token?.TokenDetail.create_timestamp, false) || '-'} />
                </VStack>
                {/* 右边 */}
                <VStack gap="26px" h="100%" alignItems="start">
                  <VTextLabelBox title="Virtual Liquidity" value={virtualLiquidityValue ? formatCurrency(virtualLiquidityValue, 2) : '-'} />
                </VStack>
              </HStack>
            )}

            <Stack
              direction={{ base: 'column', lg: 'row' }}
              pl="20px"
              pr="20px"
              mb="20px"
              w="100%"
              gap={{ base: '8px', lg: '16px' }}
              justifyContent="space-between"
              data-html2canvas-ignore
            >
              <Button
                w="100%"
                leftIcon={<Icon xlinkHref="#icon-icon_top" svgFill="primary" transform="rotate(180deg)" />}
                fontSize="14px"
                fontWeight="500"
                variant="outline"
                borderRadius="8px"
                onClick={() => captureCard(0)}
              >
                Save Image
              </Button>
              <Button
                w="100%"
                leftIcon={<Icon xlinkHref="#icon-icon_copy" svgFill="primary" />}
                fontSize="14px"
                fontWeight="500"
                variant="outline"
                borderRadius="8px"
                onClick={() => captureCard(1)}
              >
                Copy Image
              </Button>
              <Button
                w="100%"
                display="flex"
                alignItems="center"
                justifyContent="center"
                textAlign="center"
                leftIcon={<Icon xlinkHref="#icon-icon_twitter" svgFill="primary" svgW="13px" svgH="13px" />}
                fontSize="14px"
                fontWeight="500"
                borderRadius="8px"
                variant="outline"
                onClick={() => captureCard(2)}
              >
                X/Twitter
              </Button>
            </Stack>
          </VStack>
        </ModalBody>
      </ModalContent>
    </Modal>
  )
}
