import { defaultChartProps, disabledFeaturesOnMobile } from '@/constants/tvchart'
import { usePumpApiDomain } from '@/hook/common/usePumpApiDomain'
import DataFeeds from '@/utils/datafeed'
import { Box } from '@chakra-ui/react'
import { CSSProperties, useEffect, useMemo, useRef, useState } from 'react'
import ChartLoading from './ChartLoading'

// const supportedResolutions: any = {
//   5: '5m',
//   15: '15m',
//   60: '1h',
//   240: '4h',
//   '1D': '1d'
// }
const supportedResolutions: any = {
  1: '1m',
  5: '5m'
}

type TVChartContainerProps = {
  symbol: string
  id: string
  chartTimerRef: any
  changeChartTimer: any
  subscriberUIDRef: any
  changeSubscriberUIDRef: any
  changeLastPrice: any
  end_time: number
}
export default function TVChartContainer({
  symbol,
  id,
  chartTimerRef,
  changeChartTimer,
  subscriberUIDRef,
  changeSubscriberUIDRef,
  changeLastPrice,
  end_time
}: TVChartContainerProps) {
  const { fetchGetByApi } = usePumpApiDomain()
  const chartContainerRef = useRef<HTMLDivElement | null>(null)
  const tvWidgetRef = useRef<any>(null)
  const [chartReady, setChartReady] = useState(false)
  const [chartDataLoading, setChartDataLoading] = useState(false)
  const style = useMemo<CSSProperties>(() => ({ visibility: !chartDataLoading ? 'visible' : 'hidden', height: '100%' }), [chartDataLoading])
  const tokenInfoRef = useRef<any>(null)
  const isMobile = false

  useEffect(() => {
    if (symbol && id) {
      tokenInfoRef.current = `${symbol}::${id}`
    }
  }, [symbol, id])

  const fetchKLineData = async (data_type: string, start_timestamp: string, end_timestamp: string, token_info_id: string, ticker: string) => {
    const res: any = await fetchGetByApi(
      `/api/v1/queryKLineData?data_type=${data_type}&start_timestamp=${start_timestamp}&end_timestamp=${end_timestamp}&token_info_id=${token_info_id}&ticker=${ticker}`
    )

    return res
  }

  useEffect(() => {
    if (!tokenInfoRef.current) return
    const dataFeeds = new DataFeeds({
      end_time,
      symbolAndId: tokenInfoRef.current,
      changeLastPrice,
      timerInput: chartTimerRef,
      changeTimer: changeChartTimer,
      subscriberUIDRef,
      changeSubscriberUIDRef,
      fetchKLineData
    })

    const browserTimeZone = Intl.DateTimeFormat().resolvedOptions().timeZone

    const widgetOptions = {
      symbol: tokenInfoRef.current, // Default symbol pair
      timezone: browserTimeZone,
      interval: '300', // Default interval
      fullscreen: false, // Displays the chart in the fullscreen mode
      locale: 'en',
      container: chartContainerRef.current, // Reference to an attribute of a DOM element
      datafeed: dataFeeds,
      library_path: '/charting_library/',
      autosize: true,
      // enabled_features: ['iframe_loading_compatibility_mode'],
      // disabled_features: ['header_symbol_search', 'header_compare'],
      enabled_features: defaultChartProps.enabled_features,
      disabled_features: isMobile ? defaultChartProps.disabled_features.concat(disabledFeaturesOnMobile) : defaultChartProps.disabled_features,
      theme: 'dark',
      custom_css_url: '/css/tv-dark.css',
      // custom_formatters: defaultChartProps.custom_formatters,
      favorites: {
        // intervals: ['5', '15', '60', '240', 'D']
        intervals: ['1', '5']
      }
    }

    tvWidgetRef.current = new (window as any).TradingView.widget(widgetOptions)

    tvWidgetRef.current!.onChartReady(function () {
      setChartReady(true)
      const upColor = '#0EC8A8'
      const downColor = '#FF3D6B'
      const backgroundColor = '#0F0F0F'

      tvWidgetRef.current!.applyOverrides({
        'paneProperties.background': backgroundColor,
        'paneProperties.backgroundType': 'solid',
        'mainSeriesProperties.candleStyle.upColor': upColor, // 上涨蜡烛颜色（绿色）
        'mainSeriesProperties.candleStyle.downColor': downColor, // 下跌蜡烛颜色（红色）
        'mainSeriesProperties.candleStyle.borderUpColor': upColor, // 上涨蜡烛边框颜色
        'mainSeriesProperties.candleStyle.borderDownColor': downColor, // 下跌蜡烛边框颜色
        'mainSeriesProperties.candleStyle.wickUpColor': upColor, // 上涨蜡烛影线颜色
        'mainSeriesProperties.candleStyle.wickDownColor': downColor // 下跌蜡烛影线颜色
      })
      tvWidgetRef.current
        ?.activeChart()
        .onIntervalChanged()
        .subscribe(null, (interval: any) => {
          if (supportedResolutions[interval]) {
            const period = supportedResolutions[interval]
            // setPeriod(period);
          }
        })

      tvWidgetRef.current?.activeChart().dataReady(() => {
        setChartDataLoading(false)
      })
    })
    return () => {
      if (tvWidgetRef.current) {
        tvWidgetRef.current.remove()
        tvWidgetRef.current = null
        setChartReady(false)
        setChartDataLoading(true)
      }
    }
  }, [tokenInfoRef.current])

  // return {
  //   (!currentToken?.ticker || !currentToken?.token_info_id) ? <ChartLoading /> :
  //   <div style={style} ref={chartContainerRef} />
  // }
  return (
    <Box w="100%" h="100%" position="relative">
      {(!tokenInfoRef.current || !chartReady || chartDataLoading) && <ChartLoading />}
      <div style={style} ref={chartContainerRef} />
    </Box>
  )
}
