import { PumpToken } from '@/type/pump'
import useTokenPrice from '@cetus/hooks/src/useTokenPrice'
import { ClmmPoolUtil, TickMath, d, fromDecimalsAmount } from '@cetusprotocol/cetus-sui-clmm-sdk'
import { BondingCurveStatus, MEMEDecimal } from '@cetusprotocol/cetus-sui-pump-sdk'
import { SUI_DECIMALS, SUI_TYPE_ARG } from '@mysten/sui/utils'
import BN from 'bn.js'
import { useMemo } from 'react'
import { useGetCurrentSqrtPrice, useGetLiquidity } from './usePumpTokenHelper'

export function useVirtualLiquidity(info?: PumpToken) {
  const { getTokenPrice } = useTokenPrice()
  const { current_sqrt_price } = useGetCurrentSqrtPrice(info)
  const { liquidity } = useGetLiquidity(info)

  const liquidityInfo = useMemo(() => {
    if (liquidity && info && current_sqrt_price) {
      const current_price = TickMath.sqrtPriceX64ToPrice(new BN(current_sqrt_price), MEMEDecimal, SUI_DECIMALS).toString()

      let amountA
      let amountB
      if (info.status >= BondingCurveStatus.MIGRATED) {
        amountA = info.coin_a || '0'
        amountB = info.coin_b || '0'
      } else {
        const coinAmounts = ClmmPoolUtil.getCoinAmountFromLiquidity(
          new BN(liquidity),
          new BN(current_sqrt_price),
          new BN(info.init_sqrt_price),
          new BN(info.end_sqrt_price),
          true
        )

        amountA = coinAmounts.coinA.toString()
        amountB = coinAmounts.coinB.toString()
      }

      const suiPrice = getTokenPrice(SUI_TYPE_ARG)

      let totalValue = d(0)
      if (suiPrice) {
        const amountValueB = d(fromDecimalsAmount(amountB, 9)).mul(suiPrice.price)
        const amountValueA = d(fromDecimalsAmount(amountA, 9)).mul(current_price).mul(suiPrice.price)
        totalValue = amountValueB.add(amountValueA)
        console.log('🚀 ~ file: useVirtualLiquidity.ts:43 ~ virtualLiquidityValue ~ amountValueB:', {
          amountValueB: amountValueB.toString(),
          amountValueA: amountValueA.toString(),
          totalValue: totalValue.toString(),
          amountB,
          amountA,
          suiPrice
        })
        return {
          liquidityValue: totalValue.toString(),
          amountA,
          amountB
        }
      }
    }
    return undefined
  }, [liquidity, current_sqrt_price, info?.end_sqrt_price, info?.coin_a])

  return {
    virtualLiquidityValue: liquidityInfo?.liquidityValue,
    amountA: liquidityInfo?.amountA,
    amountB: liquidityInfo?.amountB
  }
}
