import { Skeleton, Stack, Text } from '@chakra-ui/react'
import React from 'react'

function Info({ label, value, isLoaded }: { label: React.ReactNode; value: React.ReactNode; isLoaded?: boolean }) {
  return (
    <Stack
      flexDir={{ base: 'row', lg: 'column' }}
      w={{ base: '100%', lg: 'auto' }}
      align="flex-start"
      gap="8px"
      justify={{ base: 'space-between', lg: 'center' }}
    >
      {typeof label === 'string' ? (
        <Text color="text_paragraph" fontSize="14px" h="14px" lineHeight="14px">
          {label}
        </Text>
      ) : (
        label
      )}
      <Skeleton isLoaded={isLoaded} h="14px" lineHeight="1">
        {typeof value === 'string' ? (
          <Text color="text_caption" fontSize="14px" h="14px" lineHeight="14px">
            {value}
          </Text>
        ) : (
          value
        )}
      </Skeleton>
    </Stack>
  )
}

export default Info
