import { useTokenTxs } from '@/hook/pump/useTokenTxs'
import { PumpToken, TokenRecord } from '@/type/pump'
import { AddressUnderline, NavLink } from '@cetus/design'
import Block from '@cetus/design/src/components/common/Block'
import useExplorer, { ExplorerType } from '@cetus/hooks/src/useExplorer'
import useWindowWidth from '@cetus/hooks/src/useWindowWidth'
import { H5MapTable, Icon, NoData, Table } from '@cetus/ui-kit'
import { addComma, cancelBubble, formatRelativeTime, fromDecimalsAmountFix } from '@cetus/utils'
import { Box, HStack, Stack, Text, VStack } from '@chakra-ui/react'
import { SUI_DECIMALS } from '@mysten/sui/utils'
import { useEffect, useState } from 'react'
import { NavigateFunction, useNavigate, useParams } from 'react-router-dom'

const getColumns = (
  navigate: NavigateFunction,
  getExplorerUrl: (address?: string, type?: ExplorerType) => string,
  tokenDecimals: number,
  creator: string
) => {
  return [
    {
      title: <Text fontSize="14px">Account</Text>,
      key: 'account',
      render: ({ swapper }: TokenRecord) => {
        return (
          <VStack align={{ base: 'flex-end', lg: 'flex-start' }} justify="center" h="100%" gap={{ base: '0px', lg: '4px' }}>
            <AddressUnderline
              address={swapper}
              color="text_caption"
              fontSize="14px"
              onClickLink={() => {
                // 钱包地址
                navigate(`/profile/${swapper}`)
              }}
            />
            {swapper === creator && (
              <Box bg="primary_yellow_opacity.10" borderRadius="4px" p="2px 4px">
                <Text color="primary_yellow" fontSize="12px">
                  Creator
                </Text>
              </Box>
            )}
          </VStack>
        )
      }
    },
    {
      title: <Text fontSize="14px">Type</Text>,
      key: 'type',
      render: ({ is_buy }: { is_buy: boolean }) => {
        if (!is_buy) {
          return (
            <Text fontWeight="500" fontSize="14px" color="primary_red">
              Sell
            </Text>
          )
        } else {
          return (
            <Text fontWeight="500" fontSize="14px" color="primary_green">
              Buy
            </Text>
          )
        }
      }
    },
    {
      title: <Text fontSize="14px">Amount</Text>,
      key: 'amount',
      render: ({ is_buy, amount_sui, amount_token, ticker }: TokenRecord) => {
        const tokens = is_buy
          ? [
              { amount: fromDecimalsAmountFix(amount_sui, SUI_DECIMALS).toString(), symbol: 'SUI' },
              { amount: fromDecimalsAmountFix(amount_token, tokenDecimals).toString(), symbol: ticker }
            ]
          : [
              { amount: fromDecimalsAmountFix(amount_token, tokenDecimals).toString(), symbol: ticker },
              { amount: fromDecimalsAmountFix(amount_sui, SUI_DECIMALS).toString(), symbol: 'SUI' }
            ]
        return (
          <Stack flexDirection={{ base: 'column', lg: 'row' }} gap={{ base: '0px', lg: '0.5rem' }}>
            <HStack justify={{ base: 'flex-end', lg: 'flex-start' }}>
              <Text color="text_caption" fontWeight="500" fontSize="14px">
                {addComma(tokens[0].amount)}
              </Text>
              <Text color="text_caption" fontWeight="500" fontSize="14px">
                {tokens[0].symbol}
              </Text>
              <Icon xlinkHref="#icon-icon_right" svgFill="text_caption" />
            </HStack>
            <HStack justify={{ base: 'flex-end', lg: 'flex-start' }}>
              <Text color="text_caption" fontWeight="500" fontSize="14px">
                {addComma(tokens[1].amount)}
              </Text>
              <Text color="text_caption" fontWeight="500" fontSize="14px">
                {tokens[1].symbol}
              </Text>
            </HStack>
          </Stack>
        )
      }
    },
    {
      title: <Text fontSize="14px">Time</Text>,
      key: 'time',
      render: ({ swap_timestamp, tx_digest }: TokenRecord) => {
        return (
          <HStack
            justify="flex-end"
            onClick={e => {
              cancelBubble(e)
              window.open(getExplorerUrl(tx_digest, 'tx'))
            }}
          >
            <Text color="text_caption" fontWeight="500" fontSize="14px">
              {formatRelativeTime(swap_timestamp, true)}
            </Text>
            <NavLink type="_blank" link={getExplorerUrl(tx_digest, 'tx')} h="20px">
              <Icon xlinkHref="#icon-icon_link" />
            </NavLink>
          </HStack>
        )
      }
    }
  ]
}

function TradeHistory({ loading, refreshFlag, token }: { token?: PumpToken; loading?: boolean; refreshFlag: number }) {
  const navigate = useNavigate()
  const { getExplorerUrl } = useExplorer()
  const { id } = useParams()
  const [page, setPage] = useState(1)
  const [changePageLoading, setChangePageLoading] = useState(false)
  const { isApp } = useWindowWidth()
  const { fetchTokenTxs, tokenRecordList, refreshLoading, lordMoreLoading, hasMoreData, maxPage } = useTokenTxs()

  useEffect(() => {
    if (id && (id || refreshFlag > 0)) {
      fetchTokenTxs({ page, page_size: 10, coin_type: id })
    }
  }, [id, refreshFlag, page])

  return (
    <Block p="20px 0">
      <Text color="text_caption" fontSize="16px" mb={{ base: '0', lg: '20px' }} pl="16px">
        Trade History
      </Text>
      {(!tokenRecordList || !tokenRecordList.length) && page === 1 && !lordMoreLoading && !loading ? (
        <NoData type="nodata" text="No trade history" border="none" />
      ) : isApp ? (
        <H5MapTable<TokenRecord>
          wrapStyle={{ p: '0 16px' }}
          dataSource={tokenRecordList}
          itemSkeletonLength={4}
          columns={getColumns(navigate, getExplorerUrl, token?.TokenDetail?.decimals as number, token?.creator as string)}
          loading={lordMoreLoading || !!loading || changePageLoading}
          rowKey="tx_digest"
          rowStyle={(_, index) => ({
            w: '100%',
            p: '24px 0',
            borderBottom: index < tokenRecordList?.length - 1 ? '1px solid' : 'none',
            borderColor: 'border',
            gap: '0px'
          })}
          pagination={{
            total: Math.min(10 * maxPage, 200),
            size: 10,
            currentPage: page,
            onChange: current => {
              setChangePageLoading
              setPage(current)
              setChangePageLoading(false)
            }
          }}
        />
      ) : (
        <Table<TokenRecord>
          columns={getColumns(navigate, getExplorerUrl, token?.TokenDetail?.decimals as number, token?.creator as string)}
          dataSource={tokenRecordList}
          onRowClick={item => window.open(getExplorerUrl(item?.tx_digest, 'tx'))}
          skeletonLength={10}
          loading={lordMoreLoading || !!loading || changePageLoading}
          rowStyle={{ h: '60px', cursor: 'pointer' }}
          pagination={{
            total: Math.min(10 * maxPage, 200),
            size: 10,
            currentPage: page,
            onChange: current => {
              setChangePageLoading
              setPage(current)
              setChangePageLoading(false)
            }
          }}
        />
      )}
    </Block>
  )
}

export default TradeHistory
