import { queryTxsByCoinType } from '@/type/api'
import { TokenRecord, TokenTxsQuery } from '@/type/pump'
import { useState } from 'react'
import { usePumpApiDomain } from '../common/usePumpApiDomain'

export function useTokenTxs() {
  const [refreshLoading, setRefreshLoading] = useState<boolean>(false)
  const [lordMoreLoading, setLordMoreLoading] = useState<boolean>(false)
  const [hasMoreData, setHasMoreData] = useState<boolean>(false)
  const [tokenRecordList, setTokenRecordList] = useState<TokenRecord[]>([])
  const [maxPage, setMaxPage] = useState<number>(0)
  const { fetchGetByApi } = usePumpApiDomain()

  const fetchTokenTxs = async (query: TokenTxsQuery) => {
    const { page, page_size = 10, coin_type } = query

    const params = new URLSearchParams({ page: String(page), page_size: String(page_size), coin_type })

    try {
      if (page === 0) {
        setRefreshLoading(true)
      } else {
        setLordMoreLoading(true)
      }

      const response = await fetchGetByApi(`${queryTxsByCoinType}?${params.toString()}`)
      const list: TokenRecord[] = response.swapTransactions
      setMaxPage(response.maxPage)
      if (list) {
        setTokenRecordList(list)

        setHasMoreData(list.length === page_size)
      } else {
        setHasMoreData(false)
      }

      console.log('🚀 ~ file: useTokenTxs.ts:20 ~ fetchTokenTxs ~ list:', list)
    } catch (error) {
      console.log('🚀 ~ file: useTokenTxs.ts:27 ~ fetchTokenTxs ~ error:', error)
    } finally {
      setRefreshLoading(false)
      setLordMoreLoading(false)
    }
  }

  return {
    maxPage,
    fetchTokenTxs,
    tokenRecordList,
    refreshLoading,
    lordMoreLoading,
    hasMoreData
  }
}
