import CurveProgress from '@/components/trade/CurveProgress'
import HolderDistribution from '@/components/trade/HolderDistribution'
import KLine from '@/components/trade/KLine'
import TradeHistory from '@/components/trade/TradeHistory'
import Introduction from '@/components/trade/introduction'
import PlaceTrade from '@/components/trade/placeTrade'
import Completed from '@/components/trade/placeTrade/Completed'
import Migrated from '@/components/trade/placeTrade/Migrated'
import useWindowWidth from '@cetus/hooks/src/useWindowWidth'
import { BackButton, Icon, RefreshButton } from '@cetus/ui-kit'
import { BondingCurveStatus } from '@cetusprotocol/cetus-sui-pump-sdk'
import { Box, HStack, Text, VStack } from '@chakra-ui/react'
import { TradeProps } from './type'

function PCTrade({ handleRefresh, loading, currentToken, refreshFlag, status }: TradeProps) {
  const { windowWidth } = useWindowWidth()
  const shouldScale = windowWidth < 960
  return (
    <Box w="100%" mt="58px" as="div">
      <HStack w="100%" justify="space-between" mb="12px">
        <BackButton />
        <HStack>
          <Icon xlinkHref="#icon-icon_priceupdated" />
          <Text>Disclaimer: Tokens listed are not affiliated with the platform. Proceed at your own risk.</Text>
          <RefreshButton handleRefresh={handleRefresh} bg="bg_primary" w="32px" h="32px" />
        </HStack>
      </HStack>
      <VStack w="100%" gap="8px">
        <Introduction loading={loading} />
        <HStack w="100%" gap="8px" align="flex-start">
          <VStack gap="8px" w={shouldScale ? 'calc(100% - 398px)' : 'calc(100% - 488px)'}>
            <KLine token={currentToken} />
            <TradeHistory token={currentToken} loading={loading} refreshFlag={refreshFlag} />
          </VStack>
          <VStack w={shouldScale ? '390px' : '480px'} gap="8px">
            {[BondingCurveStatus.CREATED, BondingCurveStatus.RAISING].includes(status) && (
              <PlaceTrade token={currentToken} refreshFlag={refreshFlag} handleRefresh={handleRefresh} />
            )}
            {status === BondingCurveStatus.COMPLETED && <Completed token={currentToken} />}
            {[BondingCurveStatus.MIGRATED, BondingCurveStatus.LP_BURNED].includes(status) && <Migrated token={currentToken} />}
            <CurveProgress loading={loading} />
            <HolderDistribution loading={loading} refreshFlag={refreshFlag} />
          </VStack>
        </HStack>
      </VStack>
    </Box>
  )
}

export default PCTrade
