import { useGetGlobalConfig } from '@/hook/pump/useGetGlobalConfig'
import { useGetMaxAmount } from '@/hook/pump/useGetMaxAmount'
import { usePumpTokenHelper } from '@/hook/pump/usePumpTokenHelper'
import useTradeTokenStore from '@/store/tradeToken'
import Block from '@cetus/design/src/components/common/Block'
import useTokenPrice from '@cetus/hooks/src/useTokenPrice'
import { formatNumber, formatPercentage, fromDecimalsAmountFix } from '@cetus/utils'
import { d, fromDecimalsAmount } from '@cetusprotocol/cetus-sui-clmm-sdk'
import { BondingCurveStatus } from '@cetusprotocol/cetus-sui-pump-sdk'
import { Progress, Skeleton, Text } from '@chakra-ui/react'
import { useMemo } from 'react'

function CurveProgress({ loading }: { loading?: boolean }) {
  const { currentToken } = useTradeTokenStore()
  const { getTokenAmountValue } = useTokenPrice()
  const { buyMaxAmountOut } = useGetMaxAmount(
    currentToken?.liquidity,
    currentToken?.current_sqrt_price,
    currentToken?.init_sqrt_price,
    currentToken?.end_sqrt_price,
    currentToken?.status
  )

  const { raising_progress } = usePumpTokenHelper(currentToken)
  const { globalConfig } = useGetGlobalConfig()

  const sui_balance = useMemo(() => {
    if (currentToken) {
      if (currentToken.status === BondingCurveStatus.RAISING || currentToken.status === BondingCurveStatus.COMPLETED) {
        return d(currentToken.sui_balance).sub(currentToken.pending_fee).toFixed(0)
      }
    }
    return '0'
  }, [currentToken])

  return (
    <Block>
      <Text color="text_caption" fontSize="16px">
        Bonding Curve Progress:{' '}
        <Skeleton display="inline-block" lineHeight="1" isLoaded={!loading}>
          {formatPercentage(raising_progress || '0')}
        </Skeleton>
      </Text>
      <Progress h="4px" value={Number(raising_progress) || 0} w="100%" m="16px 0" />
      <Text>
        When there are{' '}
        <Text as="span" color="primary">
          {formatNumber(fromDecimalsAmount(globalConfig?.bonding_curve_config.sui_amount || 0, 9))} SUI{' '}
        </Text>
        eposited into this bonding curve, all its liquidity will be migrated into Cetus CLMM pool and the initial liquidity will be burned.
        Progression increases as the price goes up. Currently there are{' '}
        <Skeleton isLoaded={!loading} display="inline-block" lineHeight="1">
          <Text as="span" color="primary">
            {fromDecimalsAmountFix(sui_balance || 0, 9)} SUI
          </Text>
        </Skeleton>{' '}
        in this bonding curve and{' '}
        <Skeleton isLoaded={!loading && !!buyMaxAmountOut} display="inline-block" lineHeight="1">
          <Text as="span" color="primary">
            {formatNumber(fromDecimalsAmount(buyMaxAmountOut, 9))} {currentToken?.TokenDetail.symbol}
          </Text>
        </Skeleton>{' '}
        still available for sale.
      </Text>
    </Block>
  )
}

export default CurveProgress
