import TokenImg from '@/components/common/TokenImg'
import TokenStatusBlock from '@/components/common/TokenStatusBlock'
import TokenShareModel from '@/components/modal/TokenShareModel'
import usePumpConfigStore from '@/store/pumpConfig'
import ExternalAlertModel from '@cetus/design/src/components/modal/ExternalAlertModel'
import useExplorer from '@cetus/hooks/src/useExplorer'
import { Icon } from '@cetus/ui-kit'
import { Decimal, formatCreatedTime, formatCurrency, formatNumber, fromDecimalsAmountFix } from '@cetus/utils'
import { BondingCurveStatus } from '@cetusprotocol/cetus-sui-pump-sdk'
import { Center, HStack, Heading, Skeleton, Text, Tooltip, VStack } from '@chakra-ui/react'
import { useState } from 'react'
import Address from './Address'
import Info from './Info'
import { IntroductionProps } from './type'

function H5Introduction({
  currentToken,
  loading,
  raising_progress,
  vol24Value,
  market_cap,
  virtualLiquidityValue,
  amountA,
  amountB
}: IntroductionProps) {
  const [isOpenShareModel, setIsOpenShareModel] = useState<boolean>(false)
  const { getExplorerUrl } = useExplorer()

  const { externalLinkAlert, setExternalLinkAlert } = usePumpConfigStore()
  const [isOpenAlert, setIsOpenAlert] = useState<boolean>(false)
  const [link, setLink] = useState<string>('')

  return (
    <VStack
      align="flex-start"
      justifyContent="center"
      w="100%"
      minH="210px"
      gap="20px"
      p="20px"
      mb="20px"
      bg="bg_secondary"
      borderRadius="20px"
      border="1px solid"
      borderColor="border"
      position="relative"
    >
      {isOpenShareModel && currentToken && (
        <TokenShareModel
          token={currentToken}
          isOpen={isOpenShareModel}
          onClose={() => {
            setIsOpenShareModel(false)
          }}
        />
      )}
      <HStack w="100%" gap={{ base: '16px', lg: '18px' }} h="100px">
        <TokenImg
          src={currentToken?.TokenDetail?.image || ''}
          wrapStyle={{ w: '100px', h: '100px', minW: '100px', minH: '100px', p: '12px' }}
          imageStyle={{ objectFit: 'cover' }}
          onClick={() => {
            setIsOpenShareModel(true)
          }}
        />
        <VStack justify="space-between" w="100%" h="100%" align="flex-start" gap="4px">
          <HStack w="100%" align="center" justifyContent="space-between">
            <Skeleton isLoaded={!!currentToken?.TokenDetail.name}>
              <Heading fontSize={{ base: '16px', lg: '20px' }} color="text_caption" h="20px" lineHeight="20px">
                {`${currentToken?.TokenDetail.name || '--'} (${currentToken?.TokenDetail.symbol || '--'})`}
              </Heading>
            </Skeleton>
          </HStack>
          <HStack h="20px" justify="space-between" w="100%">
            <Skeleton isLoaded={!!currentToken?.TokenDetail}>
              <HStack minW="20px" maxW="100px" justify="flex-start" gap="2px">
                {currentToken?.TokenDetail.website && currentToken?.TokenDetail?.website !== 'WEBSITE' && (
                  <Center w="20px" h="20px">
                    <Icon
                      xlinkHref="#icon-icon_language"
                      fontSize="18px"
                      onClick={() => {
                        if (externalLinkAlert) {
                          setLink(currentToken?.TokenDetail.website || '')
                          setIsOpenAlert(true)
                        } else {
                          window.open(currentToken?.TokenDetail.website || '')
                        }
                      }}
                    />
                  </Center>
                )}
                {currentToken?.TokenDetail?.twitter_link && currentToken?.TokenDetail?.twitter_link !== 'TWITTER' && (
                  <Center w="20px" h="20px">
                    <Icon
                      xlinkHref="#icon-icon_twitter"
                      fontSize="14px"
                      onClick={() => {
                        if (externalLinkAlert) {
                          setLink(currentToken?.TokenDetail.twitter_link || '')
                          setIsOpenAlert(true)
                        } else {
                          window.open(currentToken?.TokenDetail.twitter_link || '')
                        }
                      }}
                    />
                  </Center>
                )}
                {currentToken?.TokenDetail?.discord && currentToken?.TokenDetail?.discord !== 'DISCORD' && (
                  <Icon
                    xlinkHref="#icon-icon_discord"
                    onClick={() => {
                      if (externalLinkAlert) {
                        setLink(currentToken?.TokenDetail.discord || '')
                        setIsOpenAlert(true)
                      } else {
                        window.open(currentToken?.TokenDetail.discord || '')
                      }
                    }}
                  />
                )}

                {currentToken?.TokenDetail?.telegram_link && currentToken?.TokenDetail?.telegram_link !== 'TELEGRAM' && (
                  <Icon
                    xlinkHref="#icon-icon_telegram1"
                    onClick={() => {
                      if (externalLinkAlert) {
                        setLink(currentToken?.TokenDetail.telegram_link || '')
                        setIsOpenAlert(true)
                      } else {
                        window.open(currentToken?.TokenDetail.telegram_link || '')
                      }
                    }}
                  />
                )}
              </HStack>
            </Skeleton>
            {!loading && Number(currentToken?.status) >= BondingCurveStatus.COMPLETED && <TokenStatusBlock />}
          </HStack>
          <Address
            label="Contract"
            address={currentToken?.TokenDetail.coin_type || ''}
            url={getExplorerUrl(currentToken?.TokenDetail.coin_type, 'coin')}
            isLoaded={!!currentToken?.TokenDetail.coin_type}
          />
          <Address
            label="Creator"
            address={currentToken?.TokenDetail.creator_address || ''}
            url={getExplorerUrl(currentToken?.TokenDetail.creator_address, 'account')}
            jumpUrl={currentToken ? `/profile/${currentToken.TokenDetail.creator_address}` : undefined}
            isLoaded={!!currentToken?.TokenDetail.creator_address}
          />
        </VStack>
      </HStack>

      <Skeleton isLoaded={!!currentToken?.TokenDetail} width="100%">
        <Text lineHeight="20px" fontSize="14px" color="text_paragraph">
          {currentToken?.TokenDetail.description || '--'}
        </Text>
      </Skeleton>
      <VStack w="100%" gap="16px" mt="8px">
        <Info
          isLoaded={!loading}
          label={
            <HStack h="14px" lineHeight="14px">
              <Text fontSize="14px" color="text_paragraph">
                Price
              </Text>
              {/* <Skeleton isLoaded={!loading}>
                <Text fontSize="14px" color={color}>
                  {percentText}
                </Text>
              </Skeleton> */}
            </HStack>
          }
          value={
            currentToken?.current_ui_price ? (
              <HStack h="14px" lineHeight="14px">
                <Text fontSize="14px" color="text_caption">
                  {formatNumber(currentToken?.current_ui_price, undefined, undefined, Decimal.ROUND_DOWN)} SUI
                </Text>
              </HStack>
            ) : (
              '-'
            )
          }
        />
        <Info isLoaded={!loading && !!market_cap} label="Market Cap" value={market_cap ? '$' + formatNumber(market_cap, 2) : '-'} />

        {(currentToken?.status || 0) >= BondingCurveStatus.MIGRATED && (
          <Info
            isLoaded={!loading && !!virtualLiquidityValue}
            label={'Liquidity'}
            value={
              <Tooltip
                placement="top"
                label={
                  <VStack alignItems="start" gap="0px">
                    <Text>Pooled {currentToken?.TokenDetail.symbol}</Text>
                    <Text color="text_caption">{formatNumber(fromDecimalsAmountFix(amountA || '0', 9))}</Text>

                    <Text mt="10px">Pooled SUI</Text>
                    <Text color="text_caption">{formatNumber(fromDecimalsAmountFix(amountB || '0', 9))}</Text>
                  </VStack>
                }
              >
                <button>
                  <Text color="text_caption" fontSize="14px" h="14px" lineHeight="14px" cursor="help" textDecoration="underline dotted">
                    {virtualLiquidityValue ? formatCurrency(virtualLiquidityValue, 2) : '-'}
                  </Text>
                </button>
              </Tooltip>
            }
          />
        )}
        {(currentToken?.status || 0) < BondingCurveStatus.MIGRATED && (
          <Info
            isLoaded={!loading && !!virtualLiquidityValue}
            label={'Virtual Liquidity'}
            value={virtualLiquidityValue ? formatCurrency(virtualLiquidityValue, 2) : '-'}
          />
        )}

        <Info isLoaded={!loading && !!vol24Value} label="24H Volume" value={vol24Value ? formatNumber(vol24Value) + ' SUI' : '-'} />

        {currentToken?.TokenDetail.create_timestamp && (
          <Info
            isLoaded={!loading}
            label="Token Created"
            value={currentToken?.TokenDetail.create_timestamp ? formatCreatedTime(currentToken?.TokenDetail.create_timestamp, false) : '-'}
          />
        )}
      </VStack>

      {isOpenAlert && externalLinkAlert && (
        <ExternalAlertModel
          link={link}
          isOpen={isOpenAlert}
          onClose={(notAlert: boolean) => {
            setIsOpenAlert(false)
            setExternalLinkAlert(!notAlert)
          }}
        />
      )}
    </VStack>
  )
}

export default H5Introduction
